#!/usr/bin/env bash
# Correctifs : préfixe LIKE échappé au déplacement d'un dossier (finder) ; messages d'erreur des routeurs
# en français ; dépendances inutilisées retirées (pg, @prisma/adapter-pg, @types/pg) ; doc alignée.
# Prérequis : apply-docs-donnees-prisma.sh.
# Usage (racine du repo) : bash apply-fix-like-messages-pg.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" 2>/dev/null | grep -qF "const likePrefix"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Pourquoi tout commence par le modèle" "apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-donnees-prisma.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/trpc.mdx" "apps/web/content/docs/dev/auth/authentification.mdx" "apps/web/content/docs/dev/donnees/ecrire-et-faire-evoluer.mdx" "apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" "apps/web/content/docs/dev/front/routage.mdx" "apps/web/content/docs/dev/stockage/le-finder.mdx" "apps/web/src/features/admin/users/components/UserCard.tsx" "packages/backend/src/modules/breakingNews/router.ts" "packages/backend/src/modules/categories/router.ts" "packages/backend/src/modules/courses/router.ts" "packages/backend/src/modules/disciplineFamilies/router.ts" "packages/backend/src/modules/disciplines/router.ts" "packages/backend/src/modules/eventSessions/router.ts" "packages/backend/src/modules/events/router.ts" "packages/backend/src/modules/media/services/assertOperationsDontUnpublishReferencedAssets.service.ts" "packages/backend/src/modules/media/services/resolveGroupBaseFolder.service.ts" "packages/backend/src/modules/media/services/resolvePersoBaseFolder.service.ts" "packages/backend/src/modules/origins/router.ts" "packages/backend/src/modules/posts/router.ts" "packages/backend/src/modules/seminarSessions/router.ts" "packages/backend/src/modules/seminars/router.ts" "packages/backend/src/modules/session/router.ts" "packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" "packages/backend/src/modules/users/router.ts" "packages/backend/src/trpc/middleware.ts" "packages/contracts/src/slug/slug.schema.ts")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "const likePrefix" "packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
